:root {
  --red: #e01f2d;
  --red-deep: #8e0e1a;
  --blue: #1f4fa8;
  --ink: #080b12;
  --panel: rgba(9, 14, 24, 0.62);
  --line: rgba(255, 255, 255, 0.14);
  --gold: #ffcf5c;
  --text: #f5f7fb;
  --muted: #a8b2c4;
  --font: "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  --display: "Arial Black", "Segoe UI", Impact, sans-serif;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #0a0f1a;
  color: var(--text);
  font-family: var(--font);
  overscroll-behavior: none;
}

body { touch-action: none; user-select: none; }

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  cursor: crosshair;
}

.hidden { display: none !important; }

/* ------------- cinematic overlays ------------- */
#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 46%, transparent 45%, rgba(5, 8, 15, 0.42) 100%),
    linear-gradient(to bottom, rgba(4, 8, 16, 0.28), transparent 22%, transparent 76%, rgba(4, 8, 16, 0.35));
  z-index: 3;
}

#speedlines {
  position: fixed;
  inset: -18%;
  pointer-events: none;
  z-index: 4;
  opacity: 0;
  background: repeating-conic-gradient(from 0deg at 50% 50%,
    rgba(255, 255, 255, 0) 0deg 3.2deg,
    rgba(255, 255, 255, 0.42) 3.25deg 3.45deg,
    rgba(255, 255, 255, 0) 3.5deg 6deg);
  -webkit-mask-image: radial-gradient(circle at 50% 50%, transparent 0 34%, #000 68%, #000 100%);
  mask-image: radial-gradient(circle at 50% 50%, transparent 0 34%, #000 68%, #000 100%);
  transition: opacity 180ms linear;
  animation: rushSpin 0.55s linear infinite;
}

@keyframes rushSpin { to { transform: rotate(2.2deg) scale(1.02); } }

#reticle {
  position: fixed;
  left: 50%;
  top: 50%;
  width: 22px;
  height: 22px;
  transform: translate(-50%, -50%);
  pointer-events: none;
  z-index: 6;
  opacity: 0;
  transition: opacity 220ms ease;
}
#reticle span {
  position: absolute;
  inset: 8px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.8);
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.18), 0 0 12px rgba(255, 255, 255, 0.6);
  transition: transform 120ms ease, background 120ms ease;
}
#reticle.ready span {
  background: var(--gold);
  box-shadow: 0 0 0 2px rgba(0, 0, 0, 0.25), 0 0 18px rgba(255, 207, 92, 0.9);
  transform: scale(1.35);
}

/* ------------- HUD ------------- */
#hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  padding: max(18px, env(safe-area-inset-top)) max(18px, env(safe-area-inset-right))
           max(18px, env(safe-area-inset-bottom)) max(18px, env(safe-area-inset-left));
}

.hud-left {
  position: absolute;
  top: max(20px, env(safe-area-inset-top));
  left: max(20px, env(safe-area-inset-left));
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.panel {
  background: linear-gradient(135deg, rgba(10, 15, 26, 0.78), rgba(10, 15, 26, 0.48));
  border: 1px solid var(--line);
  border-left: 2px solid var(--red);
  border-radius: 4px;
  padding: 10px 14px 11px;
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.28);
}

.eyebrow {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.22em;
  color: var(--muted);
  text-transform: uppercase;
}

.token-row {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-family: var(--display);
  font-size: 30px;
  line-height: 1.05;
  margin-top: 2px;
}
.token-total { font-size: 13px; color: var(--muted); letter-spacing: 0.05em; font-family: var(--font); font-weight: 700; }

.meter {
  width: 148px;
  height: 4px;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.14);
  overflow: hidden;
  margin-top: 7px;
}
.meter i {
  display: block;
  height: 100%;
  width: 0%;
  border-radius: 4px;
  background: linear-gradient(90deg, var(--red), #ff7a45);
  box-shadow: 0 0 12px rgba(224, 31, 45, 0.8);
  transition: width 260ms cubic-bezier(0.22, 1, 0.36, 1);
}

.time-panel .mono { font-family: ui-monospace, "SF Mono", Menlo, monospace; font-size: 15px; letter-spacing: 0.08em; margin-top: 3px; }

.hud-right {
  position: absolute;
  top: max(20px, env(safe-area-inset-top));
  right: max(20px, env(safe-area-inset-right));
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}

.stats-panel { display: flex; align-items: center; gap: 14px; }
.stat { display: flex; flex-direction: column; align-items: flex-end; line-height: 1; }
.stat span { font-family: var(--display); font-size: 24px; font-variant-numeric: tabular-nums; }
.stat small { font-size: 8px; letter-spacing: 0.16em; color: var(--muted); margin-top: 4px; font-weight: 800; }
.divider { width: 1px; height: 28px; background: var(--line); }

.hud-buttons { display: flex; gap: 8px; pointer-events: auto; }
.icon-btn {
  width: 34px; height: 34px;
  border-radius: 50%;
  border: 1px solid var(--line);
  background: rgba(8, 12, 20, 0.66);
  color: var(--text);
  font-size: 14px;
  font-weight: 800;
  cursor: pointer;
  backdrop-filter: blur(6px);
  transition: background 140ms ease, transform 140ms ease, border-color 140ms ease;
}
.icon-btn:hover { background: rgba(224, 31, 45, 0.42); border-color: rgba(255, 255, 255, 0.4); transform: translateY(-1px); }
.icon-btn.off { color: #66708a; }

#radarWrap {
  position: absolute;
  left: max(20px, env(safe-area-inset-left));
  bottom: max(20px, env(safe-area-inset-bottom));
  width: 148px;
  height: 148px;
  border-radius: 50%;
  background: rgba(8, 12, 20, 0.55);
  border: 1px solid rgba(255, 255, 255, 0.16);
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.35), inset 0 0 30px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(6px);
  overflow: hidden;
}
#radar { width: 100%; height: 100%; display: block; }
.radar-ring {
  position: absolute;
  inset: 18%;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 50%;
  pointer-events: none;
}
.radar-n {
  position: absolute;
  top: 5px; left: 50%;
  transform: translateX(-50%);
  font-size: 8px;
  font-weight: 800;
  color: var(--muted);
  letter-spacing: 0.2em;
}

#objective {
  position: absolute;
  left: 50%;
  bottom: max(22px, env(safe-area-inset-bottom));
  transform: translateX(-50%);
  font-size: 10px;
  letter-spacing: 0.14em;
  color: rgba(255, 255, 255, 0.7);
  text-transform: uppercase;
  text-align: center;
  white-space: nowrap;
  text-shadow: 0 2px 10px rgba(0, 0, 0, 0.8);
}
#objective b { color: var(--red); letter-spacing: 0.2em; margin-right: 8px; }

#toast {
  position: absolute;
  left: 50%;
  top: 19%;
  transform: translate(-50%, -8px);
  padding: 8px 16px;
  border-radius: 999px;
  background: rgba(8, 12, 20, 0.7);
  border: 1px solid rgba(255, 207, 92, 0.4);
  color: #ffe8ac;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  opacity: 0;
  transition: opacity 220ms ease, transform 260ms cubic-bezier(0.22, 1, 0.36, 1);
  white-space: nowrap;
  backdrop-filter: blur(8px);
}
#toast.show { opacity: 1; transform: translate(-50%, 0); }

/* ------------- overlays ------------- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  background:
    radial-gradient(circle at 22% 18%, rgba(224, 31, 45, 0.2), transparent 42%),
    radial-gradient(circle at 80% 80%, rgba(31, 79, 168, 0.24), transparent 46%),
    linear-gradient(120deg, rgba(4, 7, 14, 0.9), rgba(6, 10, 20, 0.72));
  backdrop-filter: blur(3px);
  animation: fadeIn 460ms ease both;
}

@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

.overlay-grid {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.5;
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.04) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px);
  background-size: 56px 56px;
  -webkit-mask-image: radial-gradient(circle at 50% 46%, #000 10%, transparent 72%);
  mask-image: radial-gradient(circle at 50% 46%, #000 10%, transparent 72%);
}
.overlay-grid.win {
  background-image:
    linear-gradient(rgba(255, 207, 92, 0.05) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 207, 92, 0.05) 1px, transparent 1px);
}

.title-wrap {
  position: relative;
  width: min(760px, 100%);
  text-align: center;
  padding: 18px 12px;
}

.kicker {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.42em;
  color: #d7deea;
  opacity: 0.72;
  margin-bottom: 12px;
}

h1 {
  margin: 0;
  font-family: var(--display);
  font-size: clamp(46px, 9.6vw, 106px);
  line-height: 0.9;
  letter-spacing: -0.035em;
  text-transform: uppercase;
  text-shadow: 0 6px 0 rgba(0, 0, 0, 0.32), 0 24px 60px rgba(0, 0, 0, 0.5);
}
h1 .spider-red { color: #f52233; }
h2 {
  margin: 4px 0 18px;
  font-family: var(--display);
  font-size: clamp(15px, 2.4vw, 25px);
  letter-spacing: 0.52em;
  text-indent: 0.52em;
  color: #ffd66b;
  text-transform: uppercase;
  text-shadow: 0 0 28px rgba(255, 207, 92, 0.35);
}

.tagline {
  margin: 0 auto 26px;
  max-width: 560px;
  font-size: 14px;
  line-height: 1.65;
  color: #c3cbda;
}

.controls {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  max-width: 620px;
  margin: 0 auto 24px;
}
.control {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  padding: 10px 8px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 6px;
  background: rgba(10, 15, 26, 0.42);
}
.control span { font-size: 10px; color: #aeb8c9; letter-spacing: 0.05em; }
kbd {
  display: inline-block;
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.1em;
  padding: 5px 9px;
  border-radius: 4px;
  color: #fff;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.16), rgba(255, 255, 255, 0.05));
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-bottom-width: 2px;
  white-space: nowrap;
}

.touch-tip { display: none; }

.cta {
  position: relative;
  pointer-events: auto;
  font-family: var(--display);
  font-size: clamp(14px, 1.7vw, 18px);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #fff;
  padding: 17px 38px;
  border: 0;
  border-radius: 4px;
  cursor: pointer;
  background: linear-gradient(135deg, #f02637, #b60f1f 58%, #7c0713);
  box-shadow: 0 14px 34px rgba(224, 31, 45, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.32);
  transition: transform 150ms ease, box-shadow 150ms ease, filter 150ms ease;
  overflow: hidden;
}
.cta::after {
  content: "";
  position: absolute;
  top: 0; left: -60%;
  width: 42%; height: 100%;
  background: linear-gradient(100deg, transparent, rgba(255, 255, 255, 0.36), transparent);
  transform: skewX(-18deg);
  animation: shine 3.6s ease-in-out infinite;
}
@keyframes shine { 0%, 55% { left: -60%; } 80%, 100% { left: 120%; } }
.cta:hover { transform: translateY(-2px) scale(1.015); box-shadow: 0 18px 44px rgba(224, 31, 45, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.4); }
.cta:active { transform: translateY(1px) scale(0.995); }
.cta-bolt { color: #ffd66b; margin-right: 6px; }

.start-foot { margin-top: 16px; font-size: 10px; letter-spacing: 0.08em; color: #7f8aa0; }

.corner { position: absolute; width: 34px; height: 34px; border-color: rgba(255, 255, 255, 0.3); border-style: solid; pointer-events: none; }
.corner-tl { left: 26px; top: 26px; border-width: 1px 0 0 1px; }
.corner-br { right: 26px; bottom: 26px; border-width: 0 1px 1px 0; }

/* win */
.win-wrap { position: relative; width: min(640px, 100%); text-align: center; }
.win-wrap h1 { font-size: clamp(40px, 8vw, 82px); }
.win-stats {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin: 26px 0 30px;
}
.win-stats > div {
  flex: 1;
  max-width: 160px;
  padding: 14px 10px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 6px;
  background: rgba(10, 15, 26, 0.5);
}
.win-stats span { display: block; font-family: var(--display); font-size: 27px; color: #ffd66b; }
.win-stats small { display: block; margin-top: 5px; font-size: 8px; letter-spacing: 0.16em; color: var(--muted); font-weight: 800; }

/* help sheet */
.sheet {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: rgba(4, 7, 14, 0.66);
  backdrop-filter: blur(6px);
  animation: fadeIn 180ms ease both;
}
.sheet-card {
  width: min(460px, 100%);
  padding: 26px;
  border-radius: 10px;
  background: linear-gradient(160deg, #101827, #080c15);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-top: 2px solid var(--red);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.6);
  max-height: 88vh;
  overflow: auto;
}
.sheet-card h3 { margin: 0 0 16px; font-size: 13px; letter-spacing: 0.26em; }
.sheet-row { display: flex; gap: 12px; align-items: center; padding: 9px 0; border-bottom: 1px solid rgba(255, 255, 255, 0.07); }
.sheet-row kbd { flex: 0 0 auto; }
.sheet-row span { font-size: 12px; color: #b8c2d3; line-height: 1.45; }
.sheet-note { margin: 16px 0 18px; font-size: 11px; line-height: 1.6; color: #8e99ad; }
.small-cta { padding: 12px 24px; font-size: 13px; }

/* loading */
#loading {
  position: fixed;
  inset: 0;
  z-index: 60;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 18px;
  background: #080c14;
  transition: opacity 500ms ease;
}
#loading.done { opacity: 0; pointer-events: none; }
#loading p { font-size: 10px; letter-spacing: 0.34em; color: #7d879a; margin: 0; }
.loading-mark {
  width: 44px; height: 44px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.12);
  border-top-color: var(--red);
  animation: spin 0.9s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }

/* ------------- touch ------------- */
#touch {
  position: fixed;
  inset: 0;
  z-index: 15;
  pointer-events: none;
  padding: max(22px, env(safe-area-inset-bottom));
}
#stick {
  position: absolute;
  left: max(24px, env(safe-area-inset-left));
  bottom: max(28px, env(safe-area-inset-bottom));
  width: 128px;
  height: 128px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.26);
  background: radial-gradient(circle, rgba(255, 255, 255, 0.08), rgba(10, 15, 26, 0.28));
  pointer-events: auto;
  backdrop-filter: blur(4px);
  touch-action: none;
}
#stickKnob {
  position: absolute;
  left: 50%; top: 50%;
  width: 52px; height: 52px;
  margin: -26px 0 0 -26px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(255, 255, 255, 0.85), rgba(200, 210, 230, 0.4));
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.45), inset 0 1px 2px rgba(255, 255, 255, 0.7);
  transition: transform 60ms linear;
}
.stick-hint {
  position: absolute;
  bottom: -20px;
  width: 100%;
  text-align: center;
  font-size: 8px;
  letter-spacing: 0.28em;
  color: rgba(255, 255, 255, 0.55);
  font-weight: 800;
}
.touch-actions {
  position: absolute;
  right: max(24px, env(safe-area-inset-right));
  bottom: max(30px, env(safe-area-inset-bottom));
  display: flex;
  align-items: flex-end;
  gap: 14px;
  pointer-events: auto;
}
.touch-btn {
  width: 88px; height: 88px;
  border-radius: 50%;
  border: 1.5px solid rgba(255, 255, 255, 0.3);
  color: #fff;
  font-family: var(--display);
  font-size: 12px;
  letter-spacing: 0.08em;
  background: radial-gradient(circle at 35% 28%, rgba(255, 255, 255, 0.24), rgba(12, 18, 30, 0.55));
  backdrop-filter: blur(5px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.28);
  touch-action: none;
  transition: transform 80ms ease, background 80ms ease;
}
.touch-btn.web {
  width: 108px; height: 108px;
  background: radial-gradient(circle at 35% 28%, rgba(255, 96, 108, 0.95), rgba(150, 12, 26, 0.9));
  border-color: rgba(255, 190, 196, 0.5);
  box-shadow: 0 12px 34px rgba(224, 31, 45, 0.4), inset 0 1px 0 rgba(255, 255, 255, 0.35);
}
.touch-btn.small { width: 74px; height: 74px; font-size: 10px; }
.touch-btn.active { transform: scale(0.93); filter: brightness(1.2); }

/* ------------- responsive ------------- */
@media (max-width: 760px) {
  .controls { grid-template-columns: repeat(2, minmax(0, 1fr)); max-width: 430px; }
  #objective { font-size: 8px; max-width: 80vw; white-space: normal; line-height: 1.6; bottom: 150px; }
  #radarWrap { display: none; }
  .hud-left { gap: 8px; }
  .panel { padding: 8px 11px 9px; }
  .token-row { font-size: 24px; }
  .meter { width: 118px; }
  .stat span { font-size: 19px; }
  .stats-panel { gap: 10px; }
  .hud-buttons { display: none; }
  #toast { top: 15%; }
  .overlay { padding: 18px; }
  .title-wrap { padding: 8px 4px; }
}

@media (pointer: coarse) {
  .controls, .start-foot, .wide-only { display: none; }
  .touch-tip { display: block; margin: 4px 0 22px; font-size: 11px; line-height: 1.7; color: #aab5c7; }
  .touch-tip b { color: #ffd66b; }
  .cta { padding: 15px 30px; }
  #reticle { display: none; }
  #game { cursor: default; }
}

@media (max-height: 620px) {
  .tagline { margin-bottom: 14px; font-size: 12px; }
  h2 { margin-bottom: 12px; }
  .control { padding: 7px 6px; gap: 5px; }
  .start-foot { display: none; }
  .win-stats { margin: 16px 0 18px; }
}

@media (prefers-reduced-motion: reduce) {
  #speedlines, .cta::after { animation: none; }
  .overlay { animation: none; }
}

import * as THREE from '../vendor/three.module.js';

/* ============================================================
   SPIDER-MAN — WEB RUSH
   A fan-made, self-contained 3D web-swinging playground.
   Everything is procedural: no external textures or models.
   ============================================================ */

const $ = (id) => document.getElementById(id);
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;
const damp = (a, b, lambda, dt) => lerp(a, b, 1 - Math.exp(-lambda * dt));
const TAU = Math.PI * 2;
const isTouch = matchMedia('(pointer: coarse)').matches;
const reduceMotion = matchMedia('(prefers-reduced-motion: reduce)').matches;

function angleLerp(a, b, t) {
  let d = ((b - a + Math.PI) % TAU + TAU) % TAU - Math.PI;
  return a + d * t;
}

function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0; a = (a + 0x6D2B79F5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rng = mulberry32(0x5E1D3A);
const rr = (a, b) => a + rng() * (b - a);

/* ------------------------------------------------------------
   Renderer / scene
   ------------------------------------------------------------ */
const canvas = $('game');
const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance', alpha: false });
renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, isTouch ? 1.35 : 1.75));
renderer.setSize(window.innerWidth, window.innerHeight, false);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.02;
renderer.shadowMap.enabled = !isTouch;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xb9c8dc, 150, 640);

const camera = new THREE.PerspectiveCamera(62, window.innerWidth / window.innerHeight, 0.1, 2200);

const maxAniso = renderer.capabilities.getMaxAnisotropy();

/* ------------------------------------------------------------
   Sky, sun, clouds
   ------------------------------------------------------------ */
const sunDir = new THREE.Vector3(0.52, 0.58, 0.62).normalize();

const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  depthWrite: false,
  fog: false,
  uniforms: {
    topColor: { value: new THREE.Color(0x2c5a96) },
    midColor: { value: new THREE.Color(0x8fb4d8) },
    horizonColor: { value: new THREE.Color(0xffd7a4) },
    sunColor: { value: new THREE.Color(0xfff0cc) },
    sunDir: { value: sunDir.clone() }
  },
  vertexShader: /* glsl */`
    varying vec3 vDir;
    void main() {
      vDir = normalize(position);
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }`,
  fragmentShader: /* glsl */`
    varying vec3 vDir;
    uniform vec3 topColor;
    uniform vec3 midColor;
    uniform vec3 horizonColor;
    uniform vec3 sunColor;
    uniform vec3 sunDir;
    void main() {
      float h = clamp(vDir.y, -0.1, 1.0);
      vec3 col = mix(horizonColor, midColor, smoothstep(0.0, 0.22, h));
      col = mix(col, topColor, smoothstep(0.18, 0.72, h));
      float sun = max(dot(normalize(vDir), normalize(sunDir)), 0.0);
      col += sunColor * pow(sun, 420.0) * 2.2;
      col += sunColor * pow(sun, 14.0) * 0.20;
      col += horizonColor * pow(1.0 - abs(h), 8.0) * 0.10;
      gl_FragColor = vec4(col, 1.0);
    }`
});
const sky = new THREE.Mesh(new THREE.SphereGeometry(1500, 40, 22), skyMat);
sky.frustumCulled = false;
scene.add(sky);

const hemi = new THREE.HemisphereLight(0xcfe2ff, 0x5b5147, 1.15);
scene.add(hemi);

const sun = new THREE.DirectionalLight(0xffddb0, 2.5);
sun.position.set(110, 145, 120);
sun.castShadow = !isTouch;
sun.shadow.mapSize.set(isTouch ? 1024 : 2048, isTouch ? 1024 : 2048);
sun.shadow.camera.left = -95;
sun.shadow.camera.right = 95;
sun.shadow.camera.top = 95;
sun.shadow.camera.bottom = -95;
sun.shadow.camera.near = 1;
sun.shadow.camera.far = 420;
sun.shadow.bias = -0.0006;
sun.shadow.normalBias = 0.55;
scene.add(sun);
scene.add(sun.target);

const fill = new THREE.DirectionalLight(0x8fb4ff, 0.42);
fill.position.set(-80, 60, -90);
scene.add(fill);

/* soft procedural clouds */
function cloudTexture() {
  const c = document.createElement('canvas');
  c.width = c.height = 256;
  const g = c.getContext('2d');
  g.clearRect(0, 0, 256, 256);
  for (let i = 0; i < 26; i++) {
    const x = 128 + (Math.random() - 0.5) * 150;
    const y = 140 + (Math.random() - 0.5) * 70;
    const r = 22 + Math.random() * 46;
    const grd = g.createRadialGradient(x, y, 0, x, y, r);
    grd.addColorStop(0, 'rgba(255,255,255,0.5)');
    grd.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = grd;
    g.beginPath(); g.arc(x, y, r, 0, TAU); g.fill();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}
const clouds = [];
for (let i = 0; i < 11; i++) {
  const mat = new THREE.SpriteMaterial({
    map: cloudTexture(), transparent: true, opacity: 0.36 + Math.random() * 0.24,
    depthWrite: false, fog: false, color: 0xfff2e0
  });
  const s = new THREE.Sprite(mat);
  const ang = Math.random() * TAU;
  const rad = 320 + Math.random() * 520;
  s.position.set(Math.cos(ang) * rad, 145 + Math.random() * 130, Math.sin(ang) * rad);
  const sc = 180 + Math.random() * 260;
  s.scale.set(sc, sc * 0.42, 1);
  s.userData.speed = 0.55 + Math.random() * 0.7;
  clouds.push(s);
  scene.add(s);
}

/* ------------------------------------------------------------
   Procedural textures
   ------------------------------------------------------------ */
function makeCanvas(w, h, draw) {
  const c = document.createElement('canvas');
  c.width = w; c.height = h;
  draw(c.getContext('2d'), w, h);
  return c;
}
function texture(canvas, { repeat = null, srgb = true } = {}) {
  const t = new THREE.CanvasTexture(canvas);
  if (srgb) t.colorSpace = THREE.SRGBColorSpace;
  t.anisotropy = maxAniso;
  if (repeat) {
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.repeat.set(repeat[0], repeat[1]);
  }
  return t;
}

/* asphalt */
const asphaltTex = texture(makeCanvas(256, 256, (g) => {
  g.fillStyle = '#3a3f47'; g.fillRect(0, 0, 256, 256);
  for (let i = 0; i < 5200; i++) {
    const v = 30 + Math.random() * 45;
    g.fillStyle = `rgba(${v},${v + 2},${v + 6},${0.25 + Math.random() * 0.4})`;
    g.fillRect(Math.random() * 256, Math.random() * 256, 1.4, 1.4);
  }
  g.strokeStyle = 'rgba(20,22,26,0.35)'; g.lineWidth = 1;
  for (let i = 0; i < 10; i++) {
    g.beginPath();
    let x = Math.random() * 256, y = Math.random() * 256;
    g.moveTo(x, y);
    for (let k = 0; k < 5; k++) { x += (Math.random() - 0.5) * 40; y += (Math.random() - 0.5) * 40; g.lineTo(x, y); }
    g.stroke();
  }
}), { repeat: [110, 110] });

/* sidewalk pavers */
const sidewalkTex = texture(makeCanvas(256, 256, (g) => {
  g.fillStyle = '#a9a49a'; g.fillRect(0, 0, 256, 256);
  for (let y = 0; y < 4; y++) for (let x = 0; x < 4; x++) {
    const v = 158 + Math.floor(Math.random() * 26);
    g.fillStyle = `rgb(${v},${v - 3},${v - 10})`;
    g.fillRect(x * 64 + 2, y * 64 + 2, 60, 60);
  }
  g.strokeStyle = 'rgba(80,76,70,0.35)'; g.lineWidth = 2;
  for (let i = 0; i <= 4; i++) {
    g.beginPath(); g.moveTo(i * 64, 0); g.lineTo(i * 64, 256); g.stroke();
    g.beginPath(); g.moveTo(0, i * 64); g.lineTo(256, i * 64); g.stroke();
  }
}), { repeat: [4, 4] });

/* lit windows: dark base, warm glass */
function windowTexture() {
  const c = makeCanvas(128, 256, (g) => {
    g.fillStyle = '#9aa2b0'; g.fillRect(0, 0, 128, 256);
    for (let row = 0; row < 16; row++) {
      for (let col = 0; col < 8; col++) {
        const x = col * 16 + 3.5, y = row * 16 + 4;
        const lit = Math.random() < 0.4;
        if (lit) {
          const warm = Math.random();
          g.fillStyle = warm < 0.72 ? '#ffd49a' : '#fff0c9';
        } else {
          g.fillStyle = Math.random() < 0.5 ? '#39414d' : '#2c333d';
        }
        g.fillRect(x, y, 9, 9);
        g.fillStyle = 'rgba(255,255,255,0.14)';
        g.fillRect(x, y, 9, 1.6);
      }
    }
    g.strokeStyle = 'rgba(18,20,26,0.45)'; g.lineWidth = 1.4;
    for (let row = 0; row <= 16; row++) { g.beginPath(); g.moveTo(0, row * 16); g.lineTo(128, row * 16); g.stroke(); }
    for (let col = 0; col <= 8; col++) { g.beginPath(); g.moveTo(col * 16, 0); g.lineTo(col * 16, 256); g.stroke(); }
  });
  return c;
}
const windowCanvases = [windowTexture(), windowTexture(), windowTexture()];

/* suit webbing */
function suitTexture(base = '#c21622', dark = '#7d0a13') {
  const c = makeCanvas(256, 256, (g) => {
    g.fillStyle = base; g.fillRect(0, 0, 256, 256);
    const grad = g.createLinearGradient(0, 0, 0, 256);
    grad.addColorStop(0, 'rgba(255,120,120,0.22)');
    grad.addColorStop(0.5, 'rgba(0,0,0,0.02)');
    grad.addColorStop(1, 'rgba(0,0,0,0.42)');
    g.fillStyle = grad; g.fillRect(0, 0, 256, 256);
    g.strokeStyle = dark; g.globalAlpha = 0.75;
    g.lineWidth = 3.4;
    for (let x = -32; x < 288; x += 32) {
      g.beginPath(); g.moveTo(x, 0); g.lineTo(x, 256); g.stroke();
    }
    for (let y = -32; y < 288; y += 32) {
      g.beginPath();
      for (let x = 0; x <= 256; x += 16) {
        const yy = y + Math.sin((x / 256) * Math.PI * 3) * 5;
        if (x === 0) g.moveTo(x, yy); else g.lineTo(x, yy);
      }
      g.stroke();
    }
    g.globalAlpha = 1;
  });
  return texture(c);
}
const redSuitTex = suitTexture('#c81724', '#6d0710');

/* spider emblem (chest) */
const emblemTex = texture(makeCanvas(256, 256, (g) => {
  g.clearRect(0, 0, 256, 256);
  g.strokeStyle = '#10131a';
  g.fillStyle = '#10131a';
  g.lineWidth = 11;
  g.lineCap = 'round';
  // body
  g.beginPath(); g.ellipse(128, 116, 15, 34, 0, 0, TAU); g.fill();
  g.beginPath(); g.ellipse(128, 162, 21, 25, 0, 0, TAU); g.fill();
  // legs (4 per side)
  const legs = [
    [[116, 100], [78, 66], [44, 48]],
    [[116, 120], [66, 108], [30, 96]],
    [[116, 144], [70, 164], [36, 190]],
    [[116, 160], [84, 198], [60, 232]],
    [[140, 100], [178, 66], [212, 48]],
    [[140, 120], [190, 108], [226, 96]],
    [[140, 144], [186, 164], [220, 190]],
    [[140, 160], [172, 198], [196, 232]]
  ];
  for (const [a, b, c] of legs) {
    g.beginPath(); g.moveTo(a[0], a[1]); g.quadraticCurveTo(b[0], b[1], c[0], c[1]); g.stroke();
  }
}));

/* generic glow sprite */
const glowTex = texture(makeCanvas(128, 128, (g) => {
  const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grd.addColorStop(0, 'rgba(255,255,255,1)');
  grd.addColorStop(0.25, 'rgba(255,255,255,0.75)');
  grd.addColorStop(0.6, 'rgba(255,255,255,0.16)');
  grd.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grd; g.fillRect(0, 0, 128, 128);
}));
const smokeTex = texture(makeCanvas(128, 128, (g) => {
  const grd = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  grd.addColorStop(0, 'rgba(255,255,255,0.9)');
  grd.addColorStop(0.5, 'rgba(255,255,255,0.35)');
  grd.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = grd; g.fillRect(0, 0, 128, 128);
}));

/* ------------------------------------------------------------
   City generation
   ------------------------------------------------------------ */
const STEP = 48;
const BLOCK = 34;
const HALF = 3;
const CITY_RADIUS = HALF * STEP + BLOCK / 2 + 4;
const world = {
  buildings: [],
  buildingMeshes: [],
  blocks: [],
  cars: [],
  tokens: [],
  props: []
};

const roofMat = new THREE.MeshStandardMaterial({ color: 0x565d68, roughness: 0.96, metalness: 0.04 });
const roofMatDark = new THREE.MeshStandardMaterial({ color: 0x3f454f, roughness: 1 });
const concreteMat = new THREE.MeshStandardMaterial({ map: sidewalkTex, color: 0xd6d1c6, roughness: 0.94 });
const parkMat = new THREE.MeshStandardMaterial({ color: 0x5c7a4e, roughness: 1 });
const metalMat = new THREE.MeshStandardMaterial({ color: 0x9aa4b4, roughness: 0.5, metalness: 0.65 });
const darkMetal = new THREE.MeshStandardMaterial({ color: 0x3c4350, roughness: 0.6, metalness: 0.5 });
const trunkMat = new THREE.MeshStandardMaterial({ color: 0x5c4632, roughness: 1 });
const leafMat = new THREE.MeshStandardMaterial({ color: 0x2f5d3a, roughness: 0.9 });
const leafMat2 = new THREE.MeshStandardMaterial({ color: 0x3f7446, roughness: 0.9 });

const palette = [
  [0xd7dde8, 0x8e99ab],
  [0xc7d3e2, 0x7c8ca3],
  [0xd9c9ae, 0x9b8768],
  [0xc2a996, 0x8c7262],
  [0xbfc8c0, 0x76857c],
  [0xd3c8c8, 0xa58c8c],
  [0xcdd6e4, 0x8394ad]
];

const ground = new THREE.Mesh(
  new THREE.PlaneGeometry(1700, 1700),
  new THREE.MeshStandardMaterial({ map: asphaltTex, color: 0x9298a2, roughness: 0.98, metalness: 0.02 })
);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

/* sidewalk blocks */
for (let bx = -HALF; bx <= HALF; bx++) {
  for (let bz = -HALF; bz <= HALF; bz++) {
    const isPark = rng() < 0.09 && !(bx === 0 && bz === 0);
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(BLOCK, 0.36, BLOCK), isPark ? parkMat : concreteMat);
    mesh.position.set(bx * STEP, 0.18, bz * STEP);
    mesh.receiveShadow = true;
    scene.add(mesh);
    world.blocks.push({ x: bx * STEP, z: bz * STEP, park: isPark });

    if (isPark) {
      for (let t = 0; t < 7; t++) {
        const tx = bx * STEP + rr(-12, 12);
        const tz = bz * STEP + rr(-12, 12);
        if (Math.abs(tx - bx * STEP) < 3 && Math.abs(tz - bz * STEP) < 3) continue;
        const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.3, 2.6, 6), trunkMat);
        trunk.position.set(tx, 1.65, tz);
        trunk.castShadow = !isTouch;
        scene.add(trunk);
        const crown = new THREE.Mesh(new THREE.IcosahedronGeometry(rr(1.6, 2.5), 0), Math.random() < 0.5 ? leafMat : leafMat2);
        crown.position.set(tx, rr(3.3, 4.2), tz);
        crown.rotation.set(Math.random(), Math.random(), Math.random());
        crown.castShadow = !isTouch;
        scene.add(crown);
      }
    }
  }
}

function addRoofProp(cx, cz, top, w, d) {
  const roll = rng();
  const m = new THREE.Group();
  if (roll < 0.36) {
    const box = new THREE.Mesh(new THREE.BoxGeometry(rr(1.8, 3.4), rr(1, 1.8), rr(1.8, 3.2)), darkMetal);
    box.position.y = 0.8;
    box.castShadow = !isTouch;
    m.add(box);
  } else if (roll < 0.62) {
    const tank = new THREE.Mesh(new THREE.CylinderGeometry(1.25, 1.25, 2.4, 12), new THREE.MeshStandardMaterial({ color: 0x7c6650, roughness: 0.85 }));
    tank.position.y = 2.0;
    tank.castShadow = !isTouch;
    m.add(tank);
    for (let i = 0; i < 3; i++) {
      const leg = new THREE.Mesh(new THREE.BoxGeometry(0.16, 1.2, 0.16), darkMetal);
      leg.position.set(Math.cos(i / 3 * TAU) * 0.9, 0.6, Math.sin(i / 3 * TAU) * 0.9);
      m.add(leg);
    }
  } else if (roll < 0.82) {
    const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.13, rr(5, 11), 6), metalMat);
    mast.position.y = 4;
    m.add(mast);
    const light = new THREE.Mesh(new THREE.SphereGeometry(0.24, 8, 6), new THREE.MeshBasicMaterial({ color: 0xff3b30 }));
    light.position.y = 9;
    m.add(light);
  } else {
    for (let i = 0; i < 3; i++) {
      const box = new THREE.Mesh(new THREE.BoxGeometry(rr(1, 2.2), rr(0.5, 1.1), rr(1, 2.2)), roofMatDark);
      box.position.set(rr(-w * 0.28, w * 0.28), 0.5, rr(-d * 0.28, d * 0.28));
      box.castShadow = !isTouch;
      m.add(box);
    }
  }
  m.position.set(cx + rr(-w * 0.24, w * 0.24), top, cz + rr(-d * 0.24, d * 0.24));
  m.rotation.y = Math.random() * TAU;
  scene.add(m);
  world.props.push(m);
}

function addBuilding(cx, cz, w, d, h, tintIndex, opts = {}) {
  const base = 0.36;
  const [light, dark] = palette[tintIndex % palette.length];
  const canvas = windowCanvases[Math.floor(rng() * windowCanvases.length)];
  const map = texture(canvas, { repeat: [Math.max(1, Math.round(w / 4.2)), Math.max(2, Math.round(h / 4.2))] });
  const mapEm = map.clone();
  mapEm.needsUpdate = true;

  const wall = new THREE.MeshStandardMaterial({
    map,
    color: light,
    roughness: 0.86,
    metalness: 0.08,
    emissive: 0xffb766,
    emissiveMap: mapEm,
    emissiveIntensity: 0.38
  });

  const geo = new THREE.BoxGeometry(w, h, d);
  const mesh = new THREE.Mesh(geo, [wall, wall, roofMat, roofMat, wall, wall]);
  mesh.position.set(cx, base + h / 2, cz);
  mesh.castShadow = !isTouch;
  mesh.receiveShadow = true;
  scene.add(mesh);

  const b = {
    minX: cx - w / 2, maxX: cx + w / 2,
    minZ: cz - d / 2, maxZ: cz + d / 2,
    maxY: base + h, cx, cz, w, d, h
  };
  world.buildings.push(b);
  world.buildingMeshes.push(mesh);

  // parapet
  const parapet = new THREE.Mesh(new THREE.BoxGeometry(w + 0.35, 0.55, d + 0.35), roofMatDark);
  parapet.position.set(cx, base + h + 0.22, cz);
  parapet.castShadow = !isTouch;
  scene.add(parapet);

  if (opts.prop !== false) addRoofProp(cx, cz, base + h + 0.5, w, d);
  return b;
}

/* city: 7 x 7 blocks of towers */
for (let bx = -HALF; bx <= HALF; bx++) {
  for (let bz = -HALF; bz <= HALF; bz++) {
    const block = world.blocks[(bx + HALF) * (HALF * 2 + 1) + (bz + HALF)];
    if (block && block.park) continue;
    const cx = bx * STEP;
    const cz = bz * STEP;
    const centerBoost = Math.max(0, 1 - Math.hypot(bx, bz) / 4.6) * 46;

    if (bx === 0 && bz === 0) {
      // landmark tower
      addBuilding(cx, cz, 23, 23, 128, 1, { prop: false });
      const crown = new THREE.Mesh(new THREE.BoxGeometry(14, 8, 14), new THREE.MeshStandardMaterial({ color: 0x77839a, roughness: 0.6, metalness: 0.3 }));
      crown.position.set(cx, 0.36 + 128 + 4, cz);
      crown.castShadow = !isTouch;
      scene.add(crown);
      const spire = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.5, 26, 8), metalMat);
      spire.position.set(cx, 0.36 + 128 + 8 + 13, cz);
      scene.add(spire);
      const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.55, 10, 8), new THREE.MeshBasicMaterial({ color: 0xff2a2a }));
      beacon.position.set(cx, 0.36 + 128 + 8 + 26, cz);
      scene.add(beacon);
      world.beacon = beacon;
      continue;
    }

    const single = rng() < 0.24;
    const cells = single ? [[0, 0, 24, 24]] : null;

    const makePlot = (ox, oz, maxW, maxD, boost = 1) => {
      const w = rr(maxW * 0.62, maxW);
      const d = rr(maxD * 0.62, maxD);
      const h = (rr(11, 26) + centerBoost * boost + rng() * rng() * 34) * 1;
      const px = cx + ox + rr(-(maxW - w) / 2, (maxW - w) / 2);
      const pz = cz + oz + rr(-(maxD - d) / 2, (maxD - d) / 2);
      addBuilding(px, pz, w, d, h, Math.floor(rng() * palette.length));
    };

    if (cells) {
      makePlot(0, 0, 26, 26, 1.1);
    } else {
      const off = BLOCK / 4;
      const quadrants = [[-off, -off], [off, -off], [-off, off], [off, off]];
      for (const [ox, oz] of quadrants) {
        if (rng() < 0.12) continue;
        makePlot(ox, oz, BLOCK / 2 - 2, BLOCK / 2 - 2);
      }
    }
  }
}

